import (
	context "context"
	fern "github.com/go-oauth-token-optional/fern"
	fernclient "github.com/go-oauth-token-optional/fern/client"
	option "github.com/go-oauth-token-optional/fern/option"
)

client := fernclient.NewClient(
	option.WithClientCredentials(
		"<YOUR_CLIENT_ID>",
		"<YOUR_CLIENT_SECRET>",
	),
)
response, err := client.Auth.CreateOauth2Token(
	context.TODO(),
	&fern.CreateOauth2TokenRequest{
		ClientID:     "my_oauth_app_123",
		ClientSecret: "sk_live_abcdef123456789",
		GrantType: fern.String(
			"client_credentials",
		),
	},
)
